#if UNITY_EDITOR
using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using Rekindle;
namespace Rekindle.Editor {
 [InitializeOnLoad]public static class ScenePolish {
  static double next;static ScenePolish(){EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup<next||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying)return;next=EditorApplication.timeSinceStartup+3;if(File.Exists("Artifacts/polish.request")){File.Delete("Artifacts/polish.request");Run();}};}
  static Material Material(string name,Color c){string p="Assets/Rekindle/Content/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;AssetDatabase.CreateAsset(m,p);}return m;}
  static GameObject Block(string name,Vector3 p,Vector3 s,Material m,Transform parent){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
  [MenuItem("Rekindle/Polish authored scene")]public static void Run(){try{Directory.CreateDirectory("Assets/Rekindle/Resources");if(!AssetDatabase.LoadAssetAtPath<Material>("Assets/Rekindle/Resources/RekindleSparks.mat")){var sparks=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));AssetDatabase.CreateAsset(sparks,"Assets/Rekindle/Resources/RekindleSparks.mat");}if(!AssetDatabase.LoadAssetAtPath<Material>("Assets/Rekindle/Resources/RekindleThreat.mat")){var threat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));threat.color=new Color(1,.25f,.08f);AssetDatabase.CreateAsset(threat,"Assets/Rekindle/Resources/RekindleThreat.mat");}foreach(var pole in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None)){if(pole.name!="Festival pennant pole")continue;var flag=pole.Find("Golden cloth");if(flag){flag.SetParent(pole.parent,false);flag.localPosition=pole.localPosition+new Vector3(.7f,1.2f,0);flag.localScale=new Vector3(1.3f,.7f,.07f);}}var old=GameObject.Find("Authored finishing details");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Authored finishing details");var moss=Material("Warm moss",new Color(.29f,.39f,.18f));var limestone=Material("Road edging",new Color(.48f,.46f,.37f));var plaster=AssetDatabase.LoadAssetAtPath<Material>("Assets/Rekindle/Content/Materials/Lime plaster.mat");var timber=AssetDatabase.LoadAssetAtPath<Material>("Assets/Rekindle/Content/Materials/Warm oak.mat");var dark=AssetDatabase.LoadAssetAtPath<Material>("Assets/Rekindle/Content/Materials/Deep slate.mat");var gold=AssetDatabase.LoadAssetAtPath<Material>("Assets/Rekindle/Content/Materials/Soul gold.mat");var rand=new System.Random(329);
   foreach(var actor in UnityEngine.Object.FindObjectsByType<Character>(FindObjectsInactive.Include,FindObjectsSortMode.None)){var body=actor.transform.Find("Articulated figure");if(!body||body.Find("Left arm"))continue;var cloth=body.Find("Tunic").GetComponent<Renderer>().sharedMaterial;Block("Left arm",new Vector3(-.49f,1.17f,0),new Vector3(.22f,.7f,.27f),cloth,body);Block("Right arm",new Vector3(.49f,1.2f,.07f),new Vector3(.22f,.7f,.27f),cloth,body);Block("Belt",new Vector3(0,.82f,.015f),new Vector3(.76f,.12f,.5f),timber,body);Block("Belt clasp",new Vector3(0,.82f,.28f),new Vector3(.15f,.15f,.04f),gold,body);for(int side=-1;side<=1;side+=2)Block("Eye",new Vector3(side*.095f,1.91f,.225f),new Vector3(.055f,.055f,.03f),dark,body);}
   foreach(var building in UnityEngine.Object.FindObjectsByType<WorldInteractable>(FindObjectsInactive.Include,FindObjectsSortMode.None)){if(building.Kind!=InteractionKind.Building||building.Id=="garden"||building.Id=="beacon")continue;var stage=building.transform.Find("Restored");if(stage&&stage.Find("Door lintel")==null){Block("Door lintel",new Vector3(0,3.6f,-2.75f),new Vector3(6.5f,.25f,.35f),timber,stage);for(int side=-1;side<=1;side+=2){Block("Front wall",new Vector3(side*2.4f,2,-2.7f),new Vector3(1.8f,3.7f,.22f),plaster,stage);Block("Window frame",new Vector3(side*2.4f,2.35f,-2.85f),new Vector3(1.15f,1.25f,.08f),timber,stage);Block("Amber window",new Vector3(side*2.4f,2.35f,-2.91f),new Vector3(.85f,1,.05f),gold,stage);Block("Window cross",new Vector3(side*2.4f,2.35f,-2.96f),new Vector3(.08f,1.08f,.05f),timber,stage);}Block("Chimney",new Vector3(2,4.5f,1.7f),new Vector3(.85f,3,.85f),limestone,stage);}}
   for(int i=0;i<180;i++){float z=-17+i*.98f;float x=z<35?Mathf.Max(0,z)*.2f:z<80?7+Mathf.Sin((z-35)*.055f)*8:z<120?12-(z-80)*.25f:2;int side=i%2==0?-1:1;float off=z<22?5.7f:3.9f;var edge=Block("Roadside worn stone",new Vector3(x+side*off,.09f,z),new Vector3(.4f+(float)rand.NextDouble()*.4f,.18f,1),limestone,root.transform);edge.transform.localRotation=Quaternion.Euler(0,rand.Next(-15,16),0);}
   for(int i=0;i<85;i++){float angle=(float)rand.NextDouble()*Mathf.PI*2;float r=16+(float)rand.NextDouble()*23;var p=new Vector3(Mathf.Cos(angle)*r,0,Mathf.Sin(angle)*r+4);for(int k=0;k<3;k++){var tuft=Block("Valley grasses",p+new Vector3(k*.13f,.19f,k*.08f),new Vector3(.06f,.35f+(float)rand.NextDouble()*.3f,.16f),moss,root.transform);tuft.transform.localRotation=Quaternion.Euler(rand.Next(-12,12),rand.Next(0,180),rand.Next(-20,20));}}
   EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllText("Artifacts/polish-result.txt","PASS: actor arms, belts, faces; rebuilt window and roof details; road edging; hand-distributed grass clusters. "+Application.dataPath);
  }catch(Exception e){File.WriteAllText("Artifacts/polish-result.txt",e.ToString());Debug.LogException(e);}}
 }
}
